def deterministic_split(sample_id: str, seed: str = DEFAULT_SPLIT_SEED) -> str:
    value = int(sha256(f"{seed}:{sample_id}".encode("utf-8")).hexdigest()[:8], 16) / 0xFFFFFFFF
