def _suite_from_results(name: str, results: list[EvalCaseResult]) -> EvalSuiteResult:
    passed = sum(1 for result in results if result.passed)
    total = len(results)
    return EvalSuiteResult(
        name=name,
        total=total,
        passed=passed,
        failed=total - passed,
        results=tuple(results),
    )

