import {
  Body,
  Ecliptic,
  EclipticGeoMoon,
  GeoVector,
  NextMoonNode,
  NodeEventKind,
  SearchMoonNode,
  SiderealTime,
} from "astronomy-engine";
import { DimensionPerspective } from "../state/FiveSpaceState";

export type ZodiacFrame =
  | "tropical"
  | "sidereal_fagan_bradley"
  | "draconic_tropical_true";
export type ImprintSide = "personality" | "design";
export type HouseMethod = "equal";

export interface GeoLocation {
  latitude: number;
  longitude: number;
}

export interface ZodiacPosition {
  longitude: number;
  zodiac: number;
  degree: number;
  minute: number;
  second: number;
  arc: number;
  house: number;
  ascendingSide: number;
}

export interface HDResolution {
  gate: number;
  line: number;
  color: number;
  tone: number;
  base: number;
}

export interface GeonatalPlacement extends ZodiacPosition, HDResolution {
  planetary: string;
  dimension: DimensionPerspective;
  frame: ZodiacFrame;
  orientation: ImprintSide;
}

export interface GeonatalChart {
  timestamp: string;
  designTimestamp: string;
  location: GeoLocation;
  houseMethod: HouseMethod;
  trueNodeLongitude: number;
  faganBradleyAyanamsa: number;
  placements: GeonatalPlacement[];
  perspectives: Record<DimensionPerspective, GeonatalPlacement[]>;
  methods: {
    ephemeris: string;
    sidereal: string;
    draconic: string;
    design: string;
    houses: string;
  };
}

export function calculateGeonatalChart(
  timestamp: Date,
  location: GeoLocation
): GeonatalChart {
  validateLocation(location);
  const personalitySun = tropicalLongitude(Body.Sun, timestamp);
  const designTimestamp = findDesignTimestamp(timestamp, personalitySun);
  const trueNode = trueNodeLongitude(timestamp);
  const ayanamsa = faganBradleyAyanamsa(timestamp);
  const placements: GeonatalPlacement[] = [];

for (const orientation of ["personality", "design"] as const) {
    const date = orientation === "personality" ? timestamp : designTimestamp;
    const node = trueNodeLongitude(date);
    const sun = tropicalLongitude(Body.Sun, date);
    for (const [planetary, body] of BODIES) {
      const tropical =
        body === "Earth"
          ? normalize(sun + 180)
          : body === "North Node"
            ? node
            : body === "South Node"
              ? normalize(node + 180)
              : tropicalLongitude(body, date);
      for (const frame of [
        "tropical",
        "sidereal_fagan_bradley",
        "draconic_tropical_true",
      ] as const) {
        const longitude =
          frame === "tropical"
            ? tropical
            : frame === "sidereal_fagan_bradley"
              ? normalize(tropical - faganBradleyAyanamsa(date))
              : normalize(tropical - node);
        placements.push(
          makePlacement(
            planetary,
            "being",
            frame,
            orientation,
            longitude,
            date,
            location
          )
        );
      }
    }
  }

const perspectives = Object.fromEntries(
    PERSPECTIVES.map((perspective) => [
      perspective,
      placements.map((placement) => ({ ...placement, dimension: perspective })),
    ])
  ) as Record<DimensionPerspective, GeonatalPlacement[]>;

return {
    timestamp: timestamp.toISOString(),
    designTimestamp: designTimestamp.toISOString(),
    location,
    houseMethod: "equal",
    trueNodeLongitude: trueNode,
    faganBradleyAyanamsa: ayanamsa,
    placements,
    perspectives,
    methods: {
      ephemeris: "astronomy-engine 2.1.19 geocentric true-ecliptic-of-date",
      sidereal: "Fagan-Bradley J2000 offset with general-precession rate",
      draconic: "tropical longitude minus interpolated true ascending lunar node",
      design: "timestamp at 88 degrees of prior solar longitude",
      houses: "equal houses from calculated tropical ascendant",
    },
  };
}

export function humanDesignResolution(longitude: number): HDResolution {
  const angle = normalize(longitude - GATE_WHEEL_START);
  const gateIndex = Math.floor(angle / 5.625);
  let remainder = angle % 5.625;
  const line = Math.floor(remainder / 0.9375) + 1;
  remainder %= 0.9375;
  const color = Math.floor(remainder / 0.15625) + 1;
  remainder %= 0.15625;
  const tone = Math.floor(remainder / (0.15625 / 6)) + 1;
  remainder %= 0.15625 / 6;
  const base = Math.min(5, Math.floor(remainder / (0.15625 / 6 / 5)) + 1);
  return { gate: GATE_ORDER[gateIndex], line, color, tone, base };
}

export function faganBradleyAyanamsa(date: Date): number {
  const j2000 = Date.UTC(2000, 0, 1, 12);
  const tropicalYears = (date.getTime() - j2000) / (365.2425 * 86400000);
  return normalize(24.7366667 + (50.290966 / 3600) * tropicalYears);
}

function makePlacement(
  planetary: string,
  dimension: DimensionPerspective,
  frame: ZodiacFrame,
  orientation: ImprintSide,
  longitude: number,
  date: Date,
  location: GeoLocation
): GeonatalPlacement {
  const zodiacPosition = zodiacBreakdown(longitude);
  const ascendant = equalHouseAscendant(date, location);
  const house = Math.floor(normalize(longitude - ascendant) / 30) + 1;
  return {
    planetary,
    dimension,
    frame,
    orientation,
    ...zodiacPosition,
    house,
    ascendingSide: house,
    ...humanDesignResolution(longitude),
  };
}

function zodiacBreakdown(longitude: number): Omit<
  ZodiacPosition,
  "house" | "ascendingSide"
> {
  const normalized = normalize(longitude);
  const zodiac = Math.floor(normalized / 30) + 1;
  const withinSign = normalized % 30;
  const degree = Math.floor(withinSign);
  const minuteFloat = (withinSign - degree) * 60;
  const minute = Math.floor(minuteFloat);
  const secondFloat = (minuteFloat - minute) * 60;
  const second = Math.floor(secondFloat);
  const arc = Math.min(99, Math.floor((secondFloat - second) * 100));
  return { longitude: normalized, zodiac, degree, minute, second, arc };
}

function tropicalLongitude(body: Body, date: Date): number {
  if (body === Body.Moon) return normalize(EclipticGeoMoon(date).lon);
  return normalize(Ecliptic(GeoVector(body, date, true)).elon);
}

function trueNodeLongitude(date: Date): number {
  let event = SearchMoonNode(new Date(date.getTime() - 35 * 86400000));
  let previous = event;
  while (event.time.date.getTime() <= date.getTime()) {
    previous = event;
    event = NextMoonNode(event);
  }
  const before = nodeLongitudeAtEvent(previous);
  const after = nodeLongitudeAtEvent(event);
  const span = event.time.date.getTime() - previous.time.date.getTime();
  const fraction = (date.getTime() - previous.time.date.getTime()) / span;
  const delta = signedDelta(before, after);
  return normalize(before + delta * fraction);
}

function nodeLongitudeAtEvent(event: ReturnType<typeof SearchMoonNode>): number {
  const moon = EclipticGeoMoon(event.time).lon;
  return normalize(event.kind === NodeEventKind.Ascending ? moon : moon + 180);
}

function findDesignTimestamp(natal: Date, natalSun: number): Date {
  let lowDays = 70;
  let highDays = 110;
  for (let iteration = 0; iteration < 60; iteration += 1) {
    const days = (lowDays + highDays) / 2;
    const candidate = new Date(natal.getTime() - days * 86400000);
    const separation = normalize(natalSun - tropicalLongitude(Body.Sun, candidate));
    if (separation < 88) lowDays = days;
    else highDays = days;
  }
  return new Date(natal.getTime() - ((lowDays + highDays) / 2) * 86400000);
}

function equalHouseAscendant(date: Date, location: GeoLocation): number {
  const lst = normalize(SiderealTime(date) * 15 + location.longitude);
  const radians = Math.PI / 180;
  const theta = lst * radians;
  const latitude = location.latitude * radians;
  const obliquity = 23.4392911 * radians;
  const ascendant =
    Math.atan2(
      -Math.cos(theta),
      Math.sin(obliquity) * Math.tan(latitude) +
        Math.cos(obliquity) * Math.sin(theta)
    ) / radians;
  return normalize(ascendant);
}

function signedDelta(from: number, to: number): number {
  return ((to - from + 540) % 360) - 180;
}

function normalize(value: number): number {
  return ((value % 360) + 360) % 360;
}

function validateLocation(location: GeoLocation): void {
  if (
    !Number.isFinite(location.latitude) ||
    location.latitude < -90 ||
    location.latitude > 90
  ) {
    throw new Error("Latitude must be between -90 and 90 degrees");
  }
  if (
    !Number.isFinite(location.longitude) ||
    location.longitude < -180 ||
    location.longitude > 180
  ) {
    throw new Error("Longitude must be between -180 and 180 degrees");
  }
}

import { FuxiEncoder } from "../topology/FuxiEncoder";
import { DimensionPerspective } from "../state/FiveSpaceState";
import { operatorBetween } from "./KleinStrongEquivalence";

export interface SemanticTerm {
  id: string;
  value: string;
  perspective: DimensionPerspective;
  statePattern: string;
}

export interface SemanticTriple {
  id: string;
  subject: SemanticTerm;
  relation: string;
  object: SemanticTerm;
}

export interface ATOOperation {
  id: string;
  triple: SemanticTriple;
  rootPattern: string;
  changedLines: Array<1 | 2 | 3 | 4 | 5 | 6>;
  preservedDimensions: string[];
  provenanceIds: string[];
}

export interface ATOResult {
  operationId: string;
  rootPattern: string;
  resultantPattern: string;
  operatorPattern: string;
  triple: SemanticTriple;
  changedLines: Array<1 | 2 | 3 | 4 | 5 | 6>;
  preservedDimensions: string[];
  reciprocal: ATOOperation;
}

export class ATOEngine {
  transform(operation: ATOOperation): ATOResult {
    FuxiEncoder.decodePattern(operation.rootPattern);
    const uniqueLines = [...new Set(operation.changedLines)].sort() as Array<
      1 | 2 | 3 | 4 | 5 | 6
    >;
    let resultantPattern = operation.rootPattern;
    for (const line of uniqueLines) {
      resultantPattern = FuxiEncoder.flipLine(
        resultantPattern,
        (line - 1) as 0 | 1 | 2 | 3 | 4 | 5
      );
    }

const reciprocalTriple: SemanticTriple = {
      id: `${operation.triple.id}:reciprocal`,
      subject: operation.triple.object,
      relation: operation.triple.relation,
      object: operation.triple.subject,
    };
    const reciprocal: ATOOperation = {
      id: `${operation.id}:reciprocal`,
      triple: reciprocalTriple,
      rootPattern: resultantPattern,
      changedLines: uniqueLines,
      preservedDimensions: [...operation.preservedDimensions],
      provenanceIds: [...operation.provenanceIds],
    };

return {
      operationId: operation.id,
      rootPattern: operation.rootPattern,
      resultantPattern,
      operatorPattern: operatorBetween(
        operation.rootPattern,
        resultantPattern
      ).code,
      triple: operation.triple,
      changedLines: uniqueLines,
      preservedDimensions: [...operation.preservedDimensions],
      reciprocal,
    };
  }

reverse(result: ATOResult): ATOResult {
    return this.transform(result.reciprocal);
  }
}

export interface BinaryState {
  code: string;
  value: number;
  bits: BitWidth;
}

export interface CatalogEntry {
  code: string;
  number?: number;
  name: string;
}

export interface CatalogValidation {
  valid: boolean;
  duplicateCodes: string[];
  duplicateNumbers: number[];
  missingCodes: string[];
  invalidCodes: string[];
}

export function strongEquivalence(
  left: number,
  right: number,
  bits: BitWidth = 6
): number {
  const mask = (1 << bits) - 1;
  return (~(left ^ right)) & mask;
}

export function strongEquivalenceCode(left: string, right: string): string {
  validateMatchingCodes(left, right);
  const bits = left.length as BitWidth;
  return strongEquivalence(
    Number.parseInt(left, 2),
    Number.parseInt(right, 2),
    bits
  )
    .toString(2)
    .padStart(bits, "0");
}

export function binaryState(code: string): BinaryState {
  validateCode(code);
  return {
    code,
    value: Number.parseInt(code, 2),
    bits: code.length as BitWidth,
  };
}

export function operatorBetween(rootCode: string, resultantCode: string): BinaryState {
  return binaryState(strongEquivalenceCode(rootCode, resultantCode));
}

export function applyStrongEquivalence(
  stateCode: string,
  operatorCode: string
): BinaryState {
  return binaryState(strongEquivalenceCode(stateCode, operatorCode));
}

export function validateBinaryCatalog(
  entries: CatalogEntry[],
  bits: BitWidth
): CatalogValidation {
  const codeCounts = new Map<string, number>();
  const numberCounts = new Map<number, number>();
  const invalidCodes: string[] = [];

for (const entry of entries) {
    if (entry.code.length !== bits || !/^[01]+$/.test(entry.code)) {
      invalidCodes.push(entry.code);
    }
    codeCounts.set(entry.code, (codeCounts.get(entry.code) ?? 0) + 1);
    if (entry.number !== undefined) {
      numberCounts.set(entry.number, (numberCounts.get(entry.number) ?? 0) + 1);
    }
  }

const duplicateCodes = [...codeCounts.entries()]
    .filter(([, count]) => count > 1)
    .map(([code]) => code)
    .sort();
  const duplicateNumbers = [...numberCounts.entries()]
    .filter(([, count]) => count > 1)
    .map(([number]) => number)
    .sort((a, b) => a - b);
  const expectedCodes = Array.from({ length: 1 << bits }, (_, value) =>
    value.toString(2).padStart(bits, "0")
  );
  const presentCodes = new Set(entries.map((entry) => entry.code));
  const missingCodes = expectedCodes.filter((code) => !presentCodes.has(code));

return {
    valid:
      duplicateCodes.length === 0 &&
      duplicateNumbers.length === 0 &&
      missingCodes.length === 0 &&
      invalidCodes.length === 0,
    duplicateCodes,
    duplicateNumbers,
    missingCodes,
    invalidCodes,
  };
}

function validateMatchingCodes(left: string, right: string): void {
  validateCode(left);
  validateCode(right);
  if (left.length !== right.length) {
    throw new Error("Binary codes must have equal widths");
  }
}

function validateCode(code: string): void {
  if (![3, 4, 6].includes(code.length) || !/^[01]+$/.test(code)) {
    throw new Error("Binary code must contain exactly 3, 4, or 6 bits");
  }
}

