export class ToolGenomeRegistry {
  private readonly organs = new Map<string, RegisteredOrgan>();
  private readonly tools = new Map<string, ComposedTool>();
  private readonly composer = new TripletToolComposer();

registerOrgan(organ: RegisteredOrgan): void {
    if (this.organs.has(organ.id)) throw new Error(`Duplicate organ ${organ.id}`);
    this.organs.set(organ.id, structuredCloneExceptFunction(organ));
  }

compose(
    id: string,
    inputId: string,
    transformId: string,
    outputId: string,
    genome: Omit<StructuralGenome, "atoOperator">
  ): ComposedTool {
    const input = this.requireOrgan(inputId);
    const transform = this.requireOrgan(transformId);
    const output = this.requireOrgan(outputId);
    if (input.returns !== transform.accepts) {
      throw new Error(`${input.id} returns ${input.returns}; ${transform.id} accepts ${transform.accepts}`);
    }
    if (transform.returns !== output.accepts) {
      throw new Error(`${transform.id} returns ${transform.returns}; ${output.id} accepts ${output.accepts}`);
    }
    const tool: ComposedTool = {
      id,
      capabilities: [...new Set([
        ...input.capabilities,
        ...transform.capabilities,
        ...output.capabilities,
      ])],
      genome: {
        ...genome,
        atoOperator: operatorBetween(
          genome.binaryRoot,
          genome.binaryResultant
        ).code,
      },
      triplet: {
        id,
        input: input.organ,
        transform: transform.organ,
        output: output.organ,
      },
      componentIds: [inputId, transformId, outputId],
    };
    this.tools.set(id,

tool);
    return tool;
  }

async execute(id: string, input: unknown): Promise<unknown> {
    const tool = this.tools.get(id);
    if (!tool) throw new Error(`Unknown composed tool ${id}`);
    return (await this.composer.execute(tool.triplet, input)).output;
  }

match(requiredCapabilities: string[]): ComposedTool[] {
    return [...this.tools.values()].filter((tool) =>
      requiredCapabilities.every((capability) =>
        tool.capabilities.includes(capability)
      )
    );
  }

getTool(id: string): ComposedTool | undefined {
    return this.tools.get(id);
  }

private requireOrgan(id: string): RegisteredOrgan {
    const organ = this.organs.get(id);
    if (!organ) throw new Error(`Unknown organ ${id}`);
    return organ;
  }
}

function structuredCloneExceptFunction(organ: RegisteredOrgan): RegisteredOrgan {
  return {
    ...organ,
    capabilities: [...organ.capabilities],
    genome: structuredClone(organ.genome),
    organ: organ.organ,
  };
}

export interface ToolContext {
  trace: string[];
  values: Record<string, unknown>;
}

export interface ToolOrgan<Input = unknown, Output = unknown> {
  id: string;
  role: "input" | "transform" | "output";
  execute(input: Input, context: ToolContext): Output | Promise<Output>;
}

export interface ToolTriplet<Input = unknown, Intermediate = unknown, Output = unknown> {
  id: string;
  input: ToolOrgan<Input, Intermediate>;
  transform: ToolOrgan<Intermediate, Intermediate>;
  output: ToolOrgan<Intermediate, Output>;
}

export interface ToolExecution<Output> {
  toolId: string;
  output: Output;
  trace: string[];
}

export class TripletToolComposer {
  async execute<Input, Intermediate, Output>(
    tool: ToolTriplet<Input, Intermediate, Output>,
    input: Input,
    initialValues: Record<string, unknown> = {}
  ): Promise<ToolExecution<Output>> {
    const context: ToolContext = { trace: [], values: { ...initialValues } };

context.trace.push(tool.input.id);
    const acquired = await tool.input.execute(input, context);
    context.trace.push(tool.transform.id);
    const transformed = await tool.transform.execute(acquired, context);
    context.trace.push(tool.output.id);
    const output = await tool.output.execute(transformed, context);

asOrgan<Input, Intermediate, Output>(
    tool: ToolTriplet<Input, Intermediate, Output>,
    role: ToolOrgan<Input, Output>["role"]
  ): ToolOrgan<Input, Output> {
    return {
      id: tool.id,
      role,
      execute: async (input, context) => {
        const result = await this.execute(tool, input, context.values);
        context.trace.push(...result.trace);
        return result.output;
      },
    };
  }
}

import {
  KnowledgeCandidate,
  LearningRevision,
  SharedLearningMemory,
} from "../memory/SharedLearningMemory";

export interface CorrectionRequest {
  candidateId: string;
  decision: CorrectionDecision;
  reason: string;
  replacement?: KnowledgeCandidate;
}

apply(request: CorrectionRequest): LearningRevision {
    const previous = this.requireCandidate(request.candidateId);
    const next: KnowledgeCandidate = request.replacement
      ? {
          ...structuredClone(request.replacement),
          id: previous.id,
          revision: previous.revision + 1,
        }
      : {
          ...previous,
          status:
            request.decision === "approve"
              ? "approved"
              : request.decision === "reject"
                ? "rejected"
                : "superseded",
          revision: previous.revision + 1,
        };

const revision: LearningRevision = {
      id: `revision:${previous.id}:${next.revision}`,
      candidateId: previous.id,
      previous,
      next,
      reason: request.reason,
      createdAt: new Date().toISOString(),
    };
    this.memory.replaceCandidate(next);
    this.memory.recordRevision(revision);
    return revision;
  }

rollback(revisionId: string, reason: string): LearningRevision {
    const original = this.memory.getRevision(revisionId);
    if (!original) throw new Error(`Unknown revision ${revisionId}`);
    const current = this.requireCandidate(original.candidateId);
    const restored: KnowledgeCandidate = {
      ...structuredClone(original.previous),
      revision: current.revision + 1,
    };
    const rollback: LearningRevision = {
      id: `revision:${current.id}:${restored.revision}`,
      candidateId: current.id,
      previous: current,
      next: restored,
      reason,
      createdAt: new Date().toISOString(),
      reversedRevisionId: revisionId,
    };
    this.memory.replaceCandidate(restored);
    this.memory.recordRevision(rollback);
    return rollback;
  }

private requireCandidate(id: string): KnowledgeCandidate {
    const candidate = this.memory.getCandidate(id);
    if (!candidate) throw new Error(`Unknown candidate ${id}`);
    return candidate;
  }
}

import {
  DimensionPerspective,
  GeonatalAddress,
  Orientation,
  PerspectivePlacement,
} from "../state/FiveSpaceState";

export interface LCTBSignature {
  line: number;
  color: number;
  tone: number;
  base: number;
}

export interface EmergencePossibility {
  id: string;
  placementId: string;
  perspective: DimensionPerspective;
  orientation: Orientation;
  gate: number;
  lctb: LCTBSignature;
  status: "possible" | "conditioned" | "active" | "settled";
  conditionIds: string[];
}

export function possibilityFromPlacement(
  placement: PerspectivePlacement
): EmergencePossibility {
  const address: GeonatalAddress = placement.address;
  return {
    id: `emergence:${placement.id}`,
    placementId: placement.id,
    perspective: address.dimension,
    orientation: address.orientation,
    gate: address.gate,
    lctb: {
      line: address.line,
      color: address.color,
      tone: address.tone,
      base: address.base,
    },
    status: "possible",
    conditionIds: [],
  };
}

export function conditionEmergence(
  possibility: EmergencePossibility,
  conditionIds: string[]
): EmergencePossibility {
  const uniqueConditions = [...new Set(conditionIds.filter(Boolean))];
  return {
    ...possibility,
    conditionIds: uniqueConditions,
    status: uniqueConditions.length > 0 ? "conditioned" : "possible",
  };
}

export function activateEmergence(
  possibility: EmergencePossibility,
  completingConditionId: string
): EmergencePossibility {
  if (!completingConditionId.trim()) {
    throw new Error("A completing condition is required for activation");
  }
  return {
    ...possibility,
    conditionIds: [...new Set([...possibility.conditionIds, completingConditionId])],
    status: "active",
  };
}

// ============================================================================
// Contrast Resolver — Multi-axis contrastive meaning
// ============================================================================
import { CorrelativeNode, ContrastRelation } from "../models";
import { StateGraph } from "./StateGraph";

registerContrast(contrast: ContrastRelation): void {
    this.contrasts.push(contrast);
  }

getContrastsForNode(nodeId: string): ContrastRelation[] {
    return this.contrasts.filter(
      (c) => c.sourceNodeId === nodeId || c.targetNodeId === nodeId
    );
  }

getContrastsByAxis(nodeId: string, axis: string): ContrastRelation[] {
    return this.contrasts.filter(
      (c) => (c.sourceNodeId === nodeId || c.targetNodeId === nodeId) && c.axis === axis
    );
  }

getContrastPartner(nodeId: string, axis: string): CorrelativeNode | undefined {
    const c = this.contrasts.find(
      (c) => c.sourceNodeId === nodeId && c.axis === axis
    );
    if (c) return this.graph.getNode(c.targetNodeId);
    const c2 = this.contrasts.find(
      (c) => c.targetNodeId === nodeId && c.axis === axis
    );
    if (c2) return this.graph.getNode(c2.sourceNodeId);
    return undefined;
  }

getAllAxesForNode(nodeId: string): string[] {
    const axes = new Set<string>();
    for (const c of this.contrasts) {
      if (c.sourceNodeId === nodeId || c.targetNodeId === nodeId) {
        axes.add(c.axis);
      }
    }
    return Array.from(axes);
  }
}

// ============================================================================
// Neighbor Resolver — Hamming-distance and structural neighbors
// ============================================================================
import { CorrelativeNode, CorrelativeRelation } from "../models";
import { StateGraph } from "./StateGraph";
import { HammingResolver } from "../topology/HammingResolver";

getHammingNeighbors(nodeId: string, distance: number = 1): CorrelativeNode[] {
    const node = this.graph.getNode(nodeId);
    if (!node) return [];
    const patterns = HammingResolver.neighbors(node.binaryPattern, distance);
    return patterns
      .map((p) => this.graph.getNodeByBinaryPattern(p))
      .filter((n): n is CorrelativeNode => n !== undefined);
  }

getStructuralNeighbors(nodeId: string): CorrelativeNode[] {
    const relations = this.graph.getRelationsForNode(nodeId);
    return relations
      .filter((r) => r.type === "neighbor")
      .map((r) =>
        r.sourceNodeId === nodeId
          ? this.graph.getNode(r.targetNodeId)
          : this.graph.getNode(r.sourceNodeId)
      )
      .filter((n): n is CorrelativeNode => n !== undefined);
  }

getAllNeighbors(nodeId: string): CorrelativeNode[] {
    const hamming = this.getHammingNeighbors(nodeId);
    const structural = this.getStructuralNeighbors(nodeId);
    const seen = new Set(hamming.map((n) => n.id));
    for (const n of structural) {
      if (!seen.has(n.id)) hamming.push(n);
    }
    return hamming;
  }
}

export interface ReciprocalPair {
  forward: CorrelativeTransition;
  reverse: CorrelativeTransition;
  sharedVocabulary: string[];
  mirroredConcepts: string[];
  structuralSimilarity: number;
}

findReciprocal(forward: CorrelativeTransition): CorrelativeTransition | null {
    const candidates = this.graph.getOutgoingTransitions(forward.resultantNodeId);
    for (const t of candidates) {
      if (t.resultantNodeId === forward.rootNodeId) {
        return t;
      }
    }
    return null;
  }

analyzePair(forward: CorrelativeTransition): ReciprocalPair | null {
    const reverse = this.findReciprocal(forward);
    if (!reverse) return null;

if (fwInterp && rvInterp) {
      const fwTerms = new Set([
        ...fwInterp.rootMeaning,
        ...fwInterp.resultantMeaning,
      ]);
      const rvTerms = new Set([
        ...rvInterp.rootMeaning,
        ...rvInterp.resultantMeaning,
      ]);
      for (const term of fwTerms) {
        if (rvTerms.has(term)) sharedVocab.push(term);
      }
    }

return {
      forward,
      reverse,
      sharedVocabulary: sharedVocab,
      mirroredConcepts: mirrored,
      structuralSimilarity: structSim,
    };
  }

private structuralSimilarity(a: CorrelativeTransition, b: CorrelativeTransition): number {
    const aSet = new Set(a.changedDimensions);
    const bSet = new Set(b.changedDimensions);
    let common = 0;
    for (const d of aSet) if (bSet.has(d)) common++;
    const total = new Set([...a.changedDimensions, ...b.changedDimensions]).size;
    return total === 0 ? 0 : common / total;
  }

getAllReciprocalPairs(nodeId: string): ReciprocalPair[] {
    const outgoing = this.graph.getOutgoingTransitions(nodeId);
    const pairs: ReciprocalPair[] = [];
    for (const t of outgoing) {
      const pair = this.analyzePair(t);
      if (pair) pairs.push(pair);
    }
    return pairs;
  }
}

// ============================================================================
// State Graph — Unified node graph with relational geometry
// ============================================================================
import { CorrelativeNode, CorrelativeRelation, CorrelativeTransition } from "../models";

export class StateGraph {
  private nodes = new Map<string, CorrelativeNode>();
  private relations = new Map<string, CorrelativeRelation>();
  private transitions = new Map<string, CorrelativeTransition>();

addNode(node: CorrelativeNode): void {
    this.nodes.set(node.id, node);
  }

getNode(id: string): CorrelativeNode | undefined {
    return this.nodes.get(id);
  }

getAllNodes(): CorrelativeNode[] {
    return Array.from(this.nodes.values());
  }

addRelation(relation: CorrelativeRelation): void {
    this.relations.set(relation.id, relation);
    const src = this.nodes.get(relation.sourceNodeId);
    const tgt = this.nodes.get(relation.targetNodeId);
    if (src && !src.relationIds.includes(relation.id)) {
      src.relationIds.push(relation.id);
    }
    if (relation.bidirectional && tgt && !tgt.relationIds.includes(relation.id)) {
      tgt.relationIds.push(relation.id);
    }
  }

getRelation(id: string): CorrelativeRelation | undefined {
    return this.relations.get(id);
  }

getRelationsForNode(nodeId: string): CorrelativeRelation[] {
    const node = this.nodes.get(nodeId);
    if (!node) return [];
    return node.relationIds.map((id) => this.relations.get(id)!).filter(Boolean);
  }

addTransition(transition: CorrelativeTransition): void {
    this.transitions.set(transition.id, transition);
    const src = this.nodes.get(transition.rootNodeId);
    const tgt = this.nodes.get(transition.resultantNodeId);
    if (src && !src.outgoingTransitionIds.includes(transition.id)) {
      src.outgoingTransitionIds.push(transition.id);
    }
    if (tgt && !tgt.incomingTransitionIds.includes(transition.id)) {
      tgt.incomingTransitionIds.push(transition.id);
    }
  }

getTransition(id: string): CorrelativeTransition | undefined {
    return this.transitions.get(id);
  }

getOutgoingTransitions(nodeId: string): CorrelativeTransition[] {
    const node = this.nodes.get(nodeId);
    if (!node) return [];
    return node.outgoingTransitionIds.map((id) => this.transitions.get(id)!).filter(Boolean);
  }

getIncomingTransitions(nodeId: string): CorrelativeTransition[] {
    const node = this.nodes.get(nodeId);
    if (!node) return [];
    return node.incomingTransitionIds.map((id) => this.transitions.get(id)!).filter(Boolean);
  }

getAllTransitions(): CorrelativeTransition[] {
    return Array.from(this.transitions.values());
  }

getNodeByBinaryPattern(pattern: string): CorrelativeNode | undefined {
    return this.getAllNodes().find((n) => n.binaryPattern === pattern);
  }
}

