// ============================================================================
// AUTOLING — Identify axes, classes, grammar constraints, operators
// ============================================================================
import { InducedRule, RelationalPattern, SymbolicOperation, ExplanationStep, ProvenanceRecord } from "../models";

induceRule(examples: Array<{ input: RelationalPattern; output: RelationalPattern }>): InducedRule | null {
    if (examples.length < 2) return null;
    const rule: InducedRule = {
      id: `rule-${Date.now()}`,
      inputPattern: examples[0].input,
      transformation: { type: "induced_mapping", parameters: { exampleCount: examples.length } },
      outputPattern: examples[0].output,
      constraints: [],
      exceptions: [],
      supportExampleIds: examples.map((_, i) => `ex-${i}`),
      counterexampleIds: [],
      confidence: Math.min(1, examples.length * 0.25),
      status: examples.length >= 3 ? "provisional" : "candidate",
      provenance: [{
        id: `prov-${Date.now()}`, category: "derived_operator", source: "AutolingEngine",
        description: `Induced from ${examples.length} examples`, timestamp: new Date().toISOString()
      }],
      explanationTrace: [{
        step: 1, operation: "induce_rule", input: examples.length, output: "rule_created", confidence: Math.min(1, examples.length * 0.25)
      }],
    };
    this.rules.push(rule);
    return rule;
  }

getRules(): InducedRule[] {
    return this.rules;
  }

validateRule(ruleId: string, testInput: RelationalPattern): { valid: boolean; trace: ExplanationStep[] } {
    const rule = this.rules.find((r) => r.id === ruleId);
    if (!rule) return { valid: false, trace: [{ step: 1, operation: "validate", input: ruleId, output: "rule_not_found", confidence: 0 }] };
    const match = this.patternMatch(rule.inputPattern, testInput);
    return {
      valid: match,
      trace: [{ step: 1, operation: "pattern_match", input: testInput, output: match, confidence: match ? 0.9 : 0.1 }],
    };
  }

private patternMatch(a: RelationalPattern, b: RelationalPattern): boolean {
    return JSON.stringify(a.nodes.sort()) === JSON.stringify(b.nodes.sort());
  }
}

// ============================================================================
// DISEMINER — Resolve implied relationships, analogical operators, inference
// ============================================================================
import { ExplanationStep, WeightedCorrespondence, ProvenanceRecord } from "../models";

export interface InferenceResult {
  inferredRelations: WeightedCorrespondence[];
  trace: ExplanationStep[];
}

export class DiseminerEngine {
  inferMissingRelation(
    knownRelations: WeightedCorrespondence[],
    sourceId: string,
    targetId: string
  ): InferenceResult {
    const trace: ExplanationStep[] = [];
    const inferred: WeightedCorrespondence[] = [];

// Transitive closure: if A→B and B→C, infer A→C
    const direct = knownRelations.find((r) => r.sourceId === sourceId && r.targetId === targetId);
    if (direct) {
      trace.push({ step: 1, operation: "direct_check", input: `${sourceId}→${targetId}`, output: "found_direct", confidence: direct.confidence });
      return { inferredRelations: [direct], trace };
    }

const intermediates = knownRelations
      .filter((r) => r.sourceId === sourceId)
      .map((r) => r.targetId);

for (const mid of intermediates) {
      const midToTarget = knownRelations.find((r) => r.sourceId === mid && r.targetId === targetId);
      if (midToTarget) {
        const inferredRel: WeightedCorrespondence = {
          sourceId,
          targetId,
          relation: `inferred_via_${mid}`,
          context: ["transitive_inference"],
          weight: Math.min(1, midToTarget.weight * 0.7),
          confidence: Math.min(1, midToTarget.confidence * 0.7),
          provenance: [{
            id: `prov-${Date.now()}`, category: "derived_operator", source: "DiseminerEngine",
            description: `Inferred via ${mid}`, timestamp: new Date().toISOString()
          }],
        };
        inferred.push(inferredRel);
        trace.push({ step: trace.length + 1, operation: "transitive_inference", input: `${sourceId}→${mid}→${targetId}`, output: inferredRel.relation, confidence: inferredRel.confidence });
      }
    }

if (inferred.length === 0) {
      trace.push({ step: 1, operation: "search", input: `${sourceId}→${targetId}`, output: "no_path_found", confidence: 0.1 });
    }

return { inferredRelations: inferred, trace };
  }
}

export interface GrammarRule {
  id: string;
  pattern: string;
  validNext: string[];
  constraints: string[];
  version: number;
  confidence: number;
}

export class GrammarInducer {
  private rules: GrammarRule[] = [];
  private versionCounter = 1;

learn(examples: Array<{ sequence: string[]; valid: boolean }>): GrammarRule[] {
    const learned: GrammarRule[] = [];
    for (const ex of examples) {
      if (!ex.valid) continue;
      for (let i = 0; i < ex.sequence.length - 1; i++) {
        const pattern = ex.sequence[i];
        const next = ex.sequence[i + 1];
        const existing = this.rules.find((r) => r.pattern === pattern);
        if (existing) {
          if (!existing.validNext.includes(next)) {
            existing.validNext.push(next);
            existing.version++;
          }
        } else {
          const rule: GrammarRule = {
            id: `gram-${Date.now()}-${i}`,
            pattern,
            validNext: [next],
            constraints: [],
            version: this.versionCounter++,
            confidence: 0.5,
          };
          this.rules.push(rule);
          learned.push(rule);
        }
      }
    }
    return learned;
  }

validate(sequence: string[]): { valid: boolean; trace: ExplanationStep[] } {
    const trace: ExplanationStep[] = [];
    for (let i = 0; i < sequence.length - 1; i++) {
      const rule = this.rules.find((r) => r.pattern === sequence[i]);
      if (!rule || !rule.validNext.includes(sequence[i + 1])) {
        trace.push({ step: i + 1, operation: "grammar_check", input: `${sequence[i]}→${sequence[i + 1]}`, output: "invalid", confidence: 0 });
        return { valid: false, trace };
      }
    }
    trace.push({ step: 1, operation: "grammar_check", input: sequence.join(" "), output: "valid", confidence: 0.95 });
    return { valid: true, trace };
  }

getRules(): GrammarRule[] {
    return this.rules;
  }
}

// ============================================================================
// Narrative Generator — Traverse states, transitions, attractors, conflicts
// ============================================================================
import { CorrelativeTransition, ExplanationStep, GenerationResult } from "../models";

export class NarrativeGenerator {
  generate(transitions: CorrelativeTransition[], title: string = "Narrative"): GenerationResult {
    const trace: ExplanationStep[] = [];
    const sentences: string[] = [];

for (let i = 0; i < transitions.length; i++) {
      const t = transitions[i];
      const interp = t.semanticInterpretation;
      if (interp) {
        sentences.push(`From ${interp.rootMeaning.join(", ")}, through ${interp.operatorMeaning.join(", ")}, toward ${interp.resultantMeaning.join(", ")}.`);
      } else {
        sentences.push(`Transition ${t.id}: ${t.rootNodeId} → ${t.resultantNodeId} via ${t.operatorType}.`);
      }
      trace.push({ step: i + 1, operation: "narrative_step", input: t.id, output: sentences[sentences.length - 1], confidence: 0.8 });
    }

return {
      output: sentences.join(" "),
      sourceStates: transitions.map((t) => t.rootNodeId),
      rulesUsed: [],
      transformationsUsed: transitions.map((t) => t.id),
      inferredRelations: [],
      unresolvedAmbiguities: [],
      structuralValidity: 0.85,
      semanticCoherence: 0.8,
      noveltyScore: 0.3,
      explanationTrace: trace,
    };
  }
}

export class Paraphraser {
  paraphrase(input: string, relationGraph: string): { output: string; trace: ExplanationStep[] } {
    const trace: ExplanationStep[] = [];
    // Deterministic paraphrase: swap synonyms while preserving structure markers
    const synonyms: Record<string, string> = {
      create: "bring forth", initiate: "begin", transform: "transmute",
      observe: "witness", perceive: "discern", understand: "comprehend",
    };
    const words = input.split(/\s+/);
    const output = words.map((w) => synonyms[w.toLowerCase()] || w).join(" ");

return { output, trace };
  }
}

export interface ValidationResult {
  valid: boolean;
  issues: string[];
  trace: ExplanationStep[];
}

export class SymbolicValidator {
  validate(
    generated: string,
    sourceGraph: string,
    semanticCenter: string[]
  ): ValidationResult {
    const trace: ExplanationStep[] = [];
    const issues: string[] = [];

// Check semantic center preservation
    const centerPreserved = semanticCenter.some((c) => generated.toLowerCase().includes(c.toLowerCase()));
    if (!centerPreserved) {
      issues.push("Semantic center not preserved in generated text");
    }
    trace.push({ step: 1, operation: "center_preservation", input: semanticCenter, output: centerPreserved, confidence: centerPreserved ? 0.9 : 0.2 });

// Check for direction reversal markers
    if (generated.includes("reverse") || generated.includes("backward")) {
      issues.push("Possible direction reversal detected");
    }
    trace.push({ step: 2, operation: "direction_check", input: generated, output: issues.length === 0 ? "ok" : "issues_found", confidence: issues.length === 0 ? 0.9 : 0.5 });

return { valid: issues.length === 0, issues, trace };
  }
}

log(result: MCPExecutionResult): void {
    this.logs.push(result);
  }

getLogs(): MCPExecutionResult[] {
    return [...this.logs];
