  };
}

export class BeingOperator {
  apply(node: ResonanceNode, field: UnifiedFieldState): ResonanceNode {
    const updated = { ...node };
    updated.operators.being = Math.min(1, updated.operators.being + updated.activation * 0.1);
    if (updated.activation > 0.7) {
      updated.regime = "activated";
    } else if (updated.activation < 0.1) {
      updated.regime = "latent";
    }
    updated.activationHistory.push({
      timestamp: new Date().toISOString(),
      activation: updated.activation,
      tension: updated.tension,
      regime: updated.regime,
      triggeredBy: "BeingOperator",
    });
    return updated;
  }

project(field: UnifiedFieldState): UnifiedFieldState {
    const updated = { ...field };
    let totalBeing = 0;
    for (const node of updated.nodes.values()) {
      totalBeing += node.operators.being;
    }
    updated.operatorProjections.being = totalBeing / updated.nodes.size;
    return updated;
  }
}

export class DesignOperator {
  apply(node: ResonanceNode, field: UnifiedFieldState): ResonanceNode {
    const updated = { ...node };
    const neighborCount = Array.from(field.nodes.values()).filter(
      (n) => n.id !== node.id && this.topologicalDistance(node, n) < 2
    ).length;
    updated.operators.design = Math.min(1, neighborCount / 6 + 0.2);
    return updated;
  }

project(field: UnifiedFieldState): UnifiedFieldState {
    const updated = { ...field };
    let total = 0;
    for (const node of updated.nodes.values()) total += node.operators.design;
    updated.operatorProjections.design = total / updated.nodes.size;
    return updated;
  }

private topologicalDistance(a: ResonanceNode, b: ResonanceNode): number {
    let diff = 0;
    for (let i = 0; i < 6; i++) {
      if (a.lines[i] !== b.lines[i]) diff++;
    }
    return diff;
  }
}

export class EvolutionOperator {
  apply(node: ResonanceNode, field: UnifiedFieldState): ResonanceNode {
    const updated = { ...node };
    const history = updated.activationHistory;
    const recent = history.slice(-5);
    const avgRecent = recent.reduce((s, r) => s + r.activation, 0) / Math.max(1, recent.length);
    updated.operators.evolution = Math.min(1, updated.memoryGravity * 0.5 + avgRecent * 0.5);
    updated.attractorWeight = Math.min(1, updated.attractorWeight + updated.activation * 0.05);
    updated.memoryGravity = Math.min(1, updated.memoryGravity + 0.02);
    return updated;
  }

project(field: UnifiedFieldState): UnifiedFieldState {
    const updated = { ...field };
    let total = 0;
    for (const node of updated.nodes.values()) total += node.operators.evolution;
    updated.operatorProjections.evolution = total / updated.nodes.size;
    return updated;
  }
}

