export class MovementOperator {
  apply(node: ResonanceNode, field: UnifiedFieldState): ResonanceNode {
    const updated = { ...node };
    const neighbors = Array.from(field.nodes.values()).filter(
      (n) => n.id !== node.id && this.hammingDistance(node.lines, n.lines) === 1
    );
    const avgNeighborActivation = neighbors.reduce((s, n) => s + n.activation, 0) / Math.max(1, neighbors.length);
    updated.operators.movement = Math.min(1, avgNeighborActivation * 1.2);
    updated.activation = Math.min(1, updated.activation + avgNeighborActivation * 0.15);
    return updated;
  }

project(field: UnifiedFieldState): UnifiedFieldState {
    const updated = { ...field };
    let total = 0;
    for (const node of updated.nodes.values()) total += node.operators.movement;
    updated.operatorProjections.movement = total / updated.nodes.size;
    return updated;
  }

private hammingDistance(a: [number, number, number, number, number, number], b: [number, number, number, number, number, number]): number {
    let d = 0;
    for (let i = 0; i < 6; i++) if (a[i] !== b[i]) d++;
    return d;
  }
}

export class SpaceOperator {
  apply(node: ResonanceNode, field: UnifiedFieldState): ResonanceNode {
    const updated = { ...node };
    const ctx = updated.observerContext;
    updated.operators.space = Math.min(1, ctx.scale * 0.3 + updated.operators.space * 0.7);
    return updated;
  }

project(field: UnifiedFieldState): UnifiedFieldState {
    const updated = { ...field };
    let total = 0;
    for (const node of updated.nodes.values()) total += node.operators.space;
    updated.operatorProjections.space = total / updated.nodes.size;
    return updated;
  }
}

import { promises as fs } from "node:fs";
import path from "node:path";
import {
  LearningSnapshot,
  SharedLearningMemory,
} from "../memory/SharedLearningMemory";

async save(memory: SharedLearningMemory): Promise<void> {
    const directory = path.dirname(this.filePath);
    const temporaryPath = `${this.filePath}.tmp`;
    await fs.mkdir(directory, { recursive: true });
    await fs.writeFile(
      temporaryPath,
      JSON.stringify(memory.snapshot(), null, 2),
      "utf8"
    );
    await fs.rename(temporaryPath, this.filePath);
  }

async load(memory: SharedLearningMemory): Promise<boolean> {
    try {
      const raw = await fs.readFile(this.filePath, "utf8");
      memory.restore(JSON.parse(raw) as LearningSnapshot);
      return true;
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") return false;
      throw error;
    }
  }
}

import { createHash } from "node:crypto";
import { promises as fs } from "node:fs";
import path from "node:path";

export interface RAGSource {
  id: string;
  kind: "book" | "repository" | "github" | "instruction" | "generated";
  uri: string;
  title: string;
  license?: string;
}

export interface RAGChunk {
  id: string;
  sourceId: string;
  location: string;
  text: string;
  checksum: string;
}

export interface RAGHit extends RAGChunk {
  source: RAGSource;
  score: number;
}

export class SourceRAG {
  private readonly sources = new Map<string, RAGSource>();
  private readonly chunks = new Map<string, RAGChunk>();

addSource(source: RAGSource): void {
    this.sources.set(source.id, structuredClone(source));
  }

addText(source: RAGSource, text: string, location = "document"): number {
    this.addSource(source);
    const paragraphs = text
      .replace(/\r/g, "")
      .split(/\n{2,}/)
      .map((value) => value.trim())
      .filter(Boolean);
    let count = 0;
    for (let i = 0; i < paragraphs.length; i++) {
      const parts = chunk(paragraphs[i], 1200);
      for (let j = 0; j < parts.length; j++) {
        const value = parts[j];
        const checksum = createHash("sha256").update(value).digest("hex");
        const id = createHash("sha256")
          .update(`${source.id}\0${location}\0${i}\0${j}\0${checksum}`)
          .digest("hex");
        this.chunks.set(id, {
          id,
          sourceId: source.id,
          location: `${location}#${i + 1}.${j + 1}`,
          text: value,
          checksum,
        });
        count += 1;
      }
    }
    return count;
  }

async addLocalTree(source: RAGSource, root: string): Promise<number> {
    this.addSource(source);
    let count = 0;
    for (const file of await walk(root)) {
      if (!isReadableSource(file)) continue;
      const relative = path.relative(root, file).replace(/\\/g, "/");
      const text = await fs.readFile(file, "utf8");
      count += this.addText(source, text, relative);
    }
    return count;
  }

async addGitHubRepository(
    owner: string,
    repository: string,
    token = process.env.GITHUB_TOKEN
  ): Promise<number> {
    const source: RAGSource = {
      id: `github:${owner}/${repository}`,
      kind: "github",
      uri: `https://github.com/${owner}/${repository}`,
      title: `${owner}/${repository}`,
    };
    const headers: Record<string, string> = {
      Accept: "application/vnd.github+json",
      "User-Agent": "synthia-source-rag",
    };
    if (token) headers.Authorization = `Bearer ${token}`;
    const repositoryResponse = await fetch(
      `https://api.github.com/repos/${owner}/${repository}`,
      { headers }
    );
    if (!repositoryResponse.ok) {
      throw new Error(`GitHub repository lookup failed: ${repositoryResponse.status}`);
    }
    const metadata = (await repositoryResponse.json()) as {
      default_branch: string;
      license?: { spdx_id?: string };
    };
    source.license = metadata.license?.spdx_id;
    this.addSource(source);

const treeResponse = await fetch(
      `https://api.github.com/repos/${owner}/${repository}/git/trees/${encodeURIComponent(metadata.default_branch)}?recursive=1`,
      { headers }
    );
    if (!treeResponse.ok) throw new Error(`GitHub tree lookup failed: ${treeResponse.status}`);
    const tree = (await treeResponse.json()) as {
      tree: Array<{ path: string; type: string; size?: number }>;
    };
    let count = 0;
    for (const item of tree.tree) {
      if (
        item.type !== "blob" ||
        !isReadableSource(item.path) ||
        (item.size ?? 0) > 500_000
      ) continue;
      const raw = await fetch(
        `https://raw.githubusercontent.com/${owner}/${repository}/${metadata.default_branch}/${item.path}`
      );
      if (raw.ok) count += this.addText(source, await raw.text(), item.path);
    }
    return count;
  }

search(query: string, limit = 10): RAGHit[] {
    const terms = query.toLowerCase().split(/\W+/).filter((term) => term.length > 1);
    return [...this.chunks.values()]
      .map((item) => {
        const lower = item.text.toLowerCase();
        const score = terms.reduce((sum, term) => {
          const matches = lower.split(term).length - 1;
          return sum + Math.min(matches, 8);
        }, 0);
        return { item, score };
      })
      .filter(({ score }) => score > 0)
      .sort((a, b) => b.score - a.score)
      .slice(0, limit)
      .map(({ item, score }) => ({
        ...structuredClone(item),
        source: structuredClone(this.sources.get(item.sourceId)!),
        score,
      }));
  }

snapshot(): { sources: RAGSource[]; chunks: RAGChunk[] } {
    return {
      sources: [...this.sources.values()].map((source) => structuredClone(source)),
      chunks: [...this.chunks.values()].map((item) => structuredClone(item)),
    };
  }
}

function chunk(text: string, size: number): string[] {
  if (text.length <= size) return [text];
  const result: string[] = [];
  for (let start = 0; start < text.length; start += size) {
    result.push(text.slice(start, start + size));
  }
  return result;
}

async function walk(root: string): Promise<string[]> {
  const result: string[] = [];
  for (const entry of await fs.readdir(root, { withFileTypes: true })) {
    if ([".git", "node_modules", "dist", "build", "__pycache__"].includes(entry.name)) continue;
    const full = path.join(root, entry.name);
    if (entry.isDirectory()) result.push(...(await walk(full)));
    else if (entry.isFile()) result.push(full);
  }
  return result;
}

function isReadableSource(file: string): boolean {
  return /\.(md|txt|json|jsonl|ya?ml|ts|tsx|js|jsx|py|rb|cs|jl|toml)$/i.test(file);
}

scheduleRecurrence(nodeId: string, depth: number = 0): number[] {
    const offsets = this.sequence.slice(0, Math.min(depth + 3, this.sequence.length));
    this.schedule.set(nodeId, offsets);
    return offsets;
  }

getNextVisit(nodeId: string, currentTick: number): number | null {
    const offsets = this.schedule.get(nodeId);
    if (!offsets) return null;
    for (const offset of offsets) {
      const visit = currentTick + offset;
      if (visit > currentTick) return visit;
    }
    return null;
  }

getSchedule(nodeId: string): number[] {
    return this.schedule.get(nodeId) || [];
  }

remove(nodeId: string): void {
    this.schedule.delete(nodeId);
  }

static getFibonacci(n: number): number {
    if (n <= 1) return 1;
    let a = 1, b = 1;
    for (let i = 2; i <= n; i++) {
      [a, b] = [b, a + b];
    }
    return b;
  }
}

// ============================================================================
// Recurrence Queue — Priority queue for Fibonacci-scheduled revisits
// ============================================================================
interface QueueEntry {
  nodeId: string;
  tick: number;
  priority: number;
}

export class RecurrenceQueue {
  private queue: QueueEntry[] = [];
  private currentTick = 0;

enqueue(nodeId: string, tick: number, priority: number = 1): void {
    this.queue.push({ nodeId, tick, priority });
    this.queue.sort((a, b) => a.tick - b.tick || b.priority - a.priority);
  }

dequeueUpTo(tick: number): QueueEntry[] {
    const results: QueueEntry[] = [];
    while (this.queue.length > 0 && this.queue[0].tick <= tick) {
      results.push(this.queue.shift()!);
    }
    return results;
  }

advance(steps: number = 1): number {
    this.currentTick += steps;
    return this.currentTick;
  }

getCurrentTick(): number {
    return this.currentTick;
  }

getPending(): QueueEntry[] {
    return [...this.queue];
  }
}

// ============================================================================
// Attention Router — Route activation between nodes
// ============================================================================
import { ResonanceNode, UnifiedFieldState } from "../models";
import { FuxiEncoder } from "../topology/FuxiEncoder";

export class AttentionRouter {
  routeActivation(
    field: UnifiedFieldState,
    sourceId: string,
    amount: number
  ): Map<string, number> {
    const source = field.nodes.get(sourceId);
    if (!source) return new Map();

const distribution = new Map<string, number>();
    const sourcePattern = source.lines.join("");
    const neighbors = FuxiEncoder.getNeighbors(sourcePattern, 1);

for (const pattern of neighbors) {
      const idx = FuxiEncoder.decodePattern(pattern);
      const nodeId = `node-${idx}`;
      const node = field.nodes.get(nodeId);
      if (node) {
        const weight = 1 / (1 + Math.abs(node.activation - source.activation));
        distribution.set(nodeId, amount * weight * 0.5);
      }
    }
    return distribution;
  }
}

export class CoherenceRegulator {
  regulate(field: UnifiedFieldState): UnifiedFieldState {
    const updated = { ...field };
    let totalActivation = 0;
    for (const node of updated.nodes.values()) {
      totalActivation += node.activation;
    }
    const avgActivation = totalActivation / updated.nodes.size;

// Dampen runaway activation, boost latent nodes
    for (const node of updated.nodes.values()) {
      if (node.activation > avgActivation * 2) {
        node.activation *= 0.95;
        node.tension *= 0.95;
      } else if (node.activation < avgActivation * 0.1 && node.attractorWeight > 0.3) {
        node.activation = Math.min(1, node.activation + 0.05);
      }
    }

updated.coherenceScore = this.computeCoherence(updated);
    return updated;
  }

private computeCoherence(field: UnifiedFieldState): number {
    const ops = field.operatorProjections;
    const mean = (ops.being + ops.design + ops.movement + ops.evolution + ops.space) / 5;
    const variance =
      Math.pow(ops.being - mean, 2) +
      Math.pow(ops.design - mean, 2) +
      Math.pow(ops.movement - mean, 2) +
      Math.pow(ops.evolution - mean, 2) +
      Math.pow(ops.space - mean, 2);
    return Math.max(0, 1 - variance / 5);
  }
}

// ============================================================================
// Monopole Controller — Global attention and trajectory router
// ============================================================================
import { ResonanceNode, MonopoleDecision, RouteSuppression, ExplanationStep, UnifiedFieldState } from "../models";
import { AdapterRegistry } from "../adapters/AdapterRegistry";

decide(field: UnifiedFieldState): MonopoleDecision {
    const trace: ExplanationStep[] = [];
    const nodes = Array.from(field.nodes.values());

// Sort by composite score: activation + attractorWeight + tension
    const scored = nodes.map((n) => ({
      node: n,
      score: n.activation * 0.4 + n.attractorWeight * 0.3 + n.tension * 0.2 + n.operators.movement * 0.1,
    }));
    scored.sort((a, b) => b.score - a.score);

const selectedChannelIds = scored
      .slice(0, 3)
      .filter((s) => s.node.channelModes.length > 0)
      .flatMap((s) => s.node.channelModes);
    trace.push({ step: 2, operation: "select_channels", input: selectedNodeIds, output: selectedChannelIds, confidence: 0.85 });

// Detect mode mismatches and activate adapters
    for (let i = 0; i < selectedNodeIds.length; i++) {
      for (let j = i + 1; j < selectedNodeIds.length; j++) {
        const a = field.nodes.get(selectedNodeIds[i])!;
        const b = field.nodes.get(selectedNodeIds[j])!;
        if (a.circuitFamily && b.circuitFamily && a.circuitFamily !== b.circuitFamily) {
          const adapter = this.adapters.findAdapter(a.circuitFamily, b.circuitFamily);
          if (adapter) {
            activatedAdapterIds.push(adapter.id);
          } else {
            suppressedRoutes.push({
              routeId: `${a.id}→${b.id}`,
              reason: `No adapter for ${a.circuitFamily}↔${b.circuitFamily}`,
            });
          }
        }
      }
    }
    trace.push({ step: 3, operation: "resolve_adapters", input: selectedNodeIds.length, output: activatedAdapterIds.length, confidence: 0.8 });

const dominantAttractorIds = scored
      .filter((s) => s.node.attractorWeight > 0.6)
      .map((s) => s.node.id);

return {
      selectedNodeIds,
      selectedChannelIds,
      activatedAdapterIds,
      dominantAttractorIds,
      suppressedRoutes,
      coherenceScore,
      decisionTrace: trace,
    };
  }

private computeCoherence(field: UnifiedFieldState): number {
    const ops = field.operatorProjections;
    const variance =
      Math.pow(ops.being - 0.5, 2) +
      Math.pow(ops.design - 0.5, 2) +
      Math.pow(ops.movement - 0.5, 2) +
      Math.pow(ops.evolution - 0.5, 2) +
      Math.pow(ops.space - 0.5, 2);
    return Math.max(0, 1 - variance);
  }
}

