// Meaning Expander — Gather new associations
// ============================================================================
import { SemanticItem, SemanticField, CorrelativeNode, Observation } from "../models";
import { MeaningScorer } from "./MeaningScorer";

proposeCandidate(
    node: CorrelativeNode,
    term: string,
    context: string,
    sourceId: string
  ): SemanticItem {
    const candidate: SemanticItem = {
      id: `si-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
      term,
      description: `Proposed meaning for ${node.id}: ${term}`,
      weight: 0.5,
      confidence: 0.5,
      status: "candidate",
      contexts: [context],
      sourceIds: [sourceId],
      structuralSupport: {
        addressSupport: 0,
        neighborSupport: 0,
        contrastSupport: 0,
        transitionSupport: 0,
        historicalSupport: 0,
        observationalSupport: 0,
        totalScore: 0,
      },
    };
    candidate.structuralSupport = this.scorer.computeSupport(node, candidate);
    candidate.confidence = candidate.structuralSupport.totalScore;
    return candidate;
  }

expandFromObservation(node: CorrelativeNode, obs: Observation): SemanticItem[] {
    const terms = this.extractTerms(obs.content);
    return terms.map((t) => this.proposeCandidate(node, t, obs.context, obs.id));
  }

private extractTerms(content: string): string[] {
    return content
      .toLowerCase()
      .replace(/[^a-z0-9\s]/g, "")
      .split(/\s+/)
      .filter((w) => w.length > 2)
      .filter((w, i, arr) => arr.indexOf(w) === i)
      .slice(0, 5);
  }
}

export class MeaningPruner {
  prune(field: SemanticField, threshold: number = 0.15): { field: SemanticField; revisions: SemanticRevision[] } {
    const revisions: SemanticRevision[] = [];
    const allArrays: Array<SemanticItem[]> = [field.center, field.central, field.peripheral];

for (const arr of allArrays) {
      for (let i = arr.length - 1; i >= 0; i--) {
        const item = arr[i];
        if (item.confidence < threshold) {
          const prevWeight = item.weight;
          item.weight = 0;
          item.status = "rejected";
          field.rejected.push(item);
          arr.splice(i, 1);
          revisions.push({
            id: `rev-${Date.now()}-${Math.random().toString(36).slice(2)}`,
            semanticItemId: item.id,
            previousWeight: prevWeight,
            newWeight: 0,
            reason: `Confidence ${item.confidence.toFixed(3)} below threshold ${threshold}`,
            evidenceIds: item.sourceIds,
            timestamp: new Date().toISOString(),
          });
        }
      }
    }
    return { field, revisions };
  }
}

// ============================================================================
// Meaning Scorer — Multi-dimensional support scoring
// ============================================================================
import { SemanticItem, StructuralSupport, CorrelativeNode, CorrelativeRelation, CorrelativeTransition } from "../models";
import { StateGraph } from "../graph/StateGraph";
import { NeighborResolver } from "../graph/NeighborResolver";

constructor(private graph: StateGraph) {
    this.neighborResolver = new NeighborResolver(graph);
  }

computeSupport(
    node: CorrelativeNode,
    item: SemanticItem
  ): StructuralSupport {
    const addressSupport = this.scoreAddress(node, item);
    const neighborSupport = this.scoreNeighbors(node, item);
    const contrastSupport = this.scoreContrasts(node, item);
    const transitionSupport = this.scoreTransitions(node, item);
    const historicalSupport = this.scoreHistorical(node, item);
    const observationalSupport = this.scoreObservational(node, item);

return {
      addressSupport,
      neighborSupport,
      contrastSupport,
      transitionSupport,
      historicalSupport,
      observationalSupport,
      totalScore: total,
    };
  }

private scoreAddress(node: CorrelativeNode, item: SemanticItem): number {
    const addrTerms = [
      node.address.dimension,
      node.address.planet || "",
      String(node.address.gate || ""),
      String(node.address.line || ""),
    ];
    return addrTerms.some((t) => item.term.toLowerCase().includes(t.toLowerCase()) || t.toLowerCase().includes(item.term.toLowerCase()))
      ? 0.7 + Math.random() * 0.3
      : 0.3;
  }

private scoreNeighbors(node: CorrelativeNode, item: SemanticItem): number {
    const neighbors = this.neighborResolver.getAllNeighbors(node.id);
    if (neighbors.length === 0) return 0.3;
    let shared = 0;
    for (const n of neighbors) {
      const hasTerm = n.semanticField.center.some((i) => i.term === item.term) ||
        n.semanticField.central.some((i) => i.term === item.term);
      if (hasTerm) shared++;
    }
    return Math.min(1, shared / Math.max(1, neighbors.length) + 0.2);
  }

private scoreContrasts(node: CorrelativeNode, item: SemanticItem): number {
    const relations = this.graph.getRelationsForNode(node.id).filter((r) => r.type === "contrast");
    if (relations.length === 0) return 0.3;
    return 0.5;
  }

private scoreTransitions(node: CorrelativeNode, item: SemanticItem): number {
    const outgoing = this.graph.getOutgoingTransitions(node.id);
    const incoming = this.graph.getIncomingTransitions(node.id);
    if (outgoing.length + incoming.length === 0) return 0.3;
    return 0.6;
  }

private scoreHistorical(node: CorrelativeNode, item: SemanticItem): number {
    return item.sourceIds.length > 0 ? 0.5 + Math.min(0.5, item.sourceIds.length * 0.1) : 0.2;
  }

private scoreObservational(node: CorrelativeNode, item: SemanticItem): number {
    return item.contexts.length > 0 ? 0.5 + Math.min(0.5, item.contexts.length * 0.1) : 0.2;
  }
}

// ============================================================================
// Semantic Attractor — Node as a center of semantic gravity
// ============================================================================
import {
  SemanticItem, SemanticField, StructuralSupport, ExplanationStep, CorrelativeNode
} from "../models";

export class SemanticAttractor {
  private weights = {
    addressSupport: 0.20,
    neighborSupport: 0.15,
    contrastSupport: 0.15,
    transitionSupport: 0.20,
    historicalSupport: 0.10,
    observationalSupport: 0.20,
  };

setWeights(w: Partial<typeof this.weights>): void {
    this.weights = { ...this.weights, ...w };
  }

scoreItem(item: SemanticItem): number {
    const s = item.structuralSupport;
    return (
      s.addressSupport * this.weights.addressSupport +
      s.neighborSupport * this.weights.neighborSupport +
      s.contrastSupport * this.weights.contrastSupport +
      s.transitionSupport * this.weights.transitionSupport +
      s.historicalSupport * this.weights.historicalSupport +
      s.observationalSupport * this.weights.observationalSupport
    );
  }

classify(score: number): SemanticItem["status"] {
    if (score >= 0.80) return "central";
    if (score >= 0.60) return "supporting";
    if (score >= 0.40) return "peripheral";
    return "rejected";
  }

computeCentroid(field: SemanticField): number[] | undefined {
    const all = [...field.center, ...field.central, ...field.peripheral];
    if (all.length === 0) return undefined;
    const dim = 8;
    const vec = new Array(dim).fill(0);
    let totalWeight = 0;
    for (const item of all) {
      const hash = this.hashString(item.term);
      for (let i = 0; i < dim; i++) {
        vec[i] += hash[i] * item.weight;
      }
      totalWeight += item.weight;
    }
    if (totalWeight === 0) return undefined;
    return vec.map((v) => v / totalWeight);
  }

private hashString(s: string): number[] {
    const dim = 8;
    const vec = new Array(dim).fill(0);
    for (let i = 0; i < s.length; i++) {
      vec[i % dim] += s.charCodeAt(i) / 1000;
    }
    return vec;
  }

updateField(field: SemanticField): SemanticField {
    for (const item of [...field.center, ...field.central, ...field.peripheral, ...field.rejected]) {
      const score = this.scoreItem(item);
      item.confidence = score;
      item.status = this.classify(score);
    }
    field.centroid = this.computeCentroid(field);
    const totalItems = field.center.length + field.central.length + field.peripheral.length + field.rejected.length;
    field.coherenceScore = totalItems > 0
      ? (field.center.length * 1.0 + field.central.length * 0.7 + field.peripheral.length * 0.4) / totalItems
      : 0;
    return field;
  }
}

