def _active_gate_source_items(chart: HumanDesignChart, gates: tuple[int | None, ...]) -> tuple[tuple[str, object | None], ...]:
    active = {gate.gate for gate in chart.activated_gates}
    items: list[tuple[str, object | None]] = []
    seen: set[int] = set()
    for gate in gates:
        if gate is None or gate not in active or gate in seen:
            continue
        seen.add(gate)
        items.append(("gate", get_gate_card(gate)))
    return tuple(items)

def _open_center_source_items(chart: HumanDesignChart) -> tuple[tuple[str, object | None], ...]:
    return tuple(
        ("center", get_center_card(center.code))
        for center in chart.centers
        if not center.defined
    )

def _sources(*items: tuple[str, object | None]) -> tuple[SourceReference, ...]:
    sources: list[SourceReference] = []
    for kind, card in items:
        if card is None:
            continue
        sources.append(to_source_reference(kind, card))  # type: ignore[arg-type]
    return _unique_sources(tuple(sources))

def _unique_sources(sources: tuple[SourceReference, ...]) -> tuple[SourceReference, ...]:
    seen: set[tuple[str, str, str]] = set()
    unique: list[SourceReference] = []
    for source in sources:
        key = (source.kind, source.code, source.path)
        if key in seen:
            continue
        seen.add(key)
        unique.append(source)
    return tuple(unique)

def analyze_forced_choice_experiment(payload: dict[str, Any] | str | Path) -> ForcedChoiceExperimentResult:
    data = _load_payload(payload)
    total_trials, correct_trials = _extract_counts(data)
    options_per_trial = int(data.get("options_per_trial") or _infer_options_per_trial(data))
    if options_per_trial < 2:
        raise ValueError("options_per_trial must be >= 2")
    if total_trials <= 0:
        raise ValueError("experiment must contain at least one trial")
    if correct_trials < 0 or correct_trials > total_trials:
        raise ValueError("correct trial count is outside valid range")

def _load_payload(payload: dict[str, Any] | str | Path) -> dict[str, Any]:
    if isinstance(payload, dict):
        return payload
    return json.loads(Path(payload).read_text(encoding="utf-8"))

def _extract_counts(data: dict[str, Any]) -> tuple[int, int]:
    trials = data.get("trials")
    if trials:
        total = len(trials)
        correct = sum(1 for trial in trials if trial.get("selected_option_id") == trial.get("correct_option_id"))
        return total, correct
    summary = data.get("summary")
    if summary:
        return int(summary["trials"]), int(summary["correct"])
    raise ValueError("experiment data must include either trials[] or summary")

def _infer_options_per_trial(data: dict[str, Any]) -> int:
    trials = data.get("trials") or []
    option_counts = [len(trial.get("option_ids", ())) for trial in trials if trial.get("option_ids")]
    if not option_counts:
        raise ValueError("options_per_trial is required when raw trials do not include option_ids")
    first = option_counts[0]
    if any(count != first for count in option_counts):
        raise ValueError("all trials must use the same number of options")
    return first

def _wilson_interval(correct: int, total: int, z: float = 1.959963984540054) -> tuple[float, float]:
    proportion = correct / total
    denominator = 1 + z**2 / total
    center = (proportion + z**2 / (2 * total)) / denominator
    margin = z * sqrt((proportion * (1 - proportion) + z**2 / (4 * total)) / total) / denominator
    return max(0.0, center - margin), min(1.0, center + margin)

def _binomial_survival(k: int, n: int, p: float) -> float:
    probability = 0.0
    for successes in range(k, n + 1):
        probability += comb(n, successes) * (p**successes) * ((1 - p) ** (n - successes))
    return min(1.0, probability)

def _evidence_status(status: str, passed_statistical_threshold: bool) -> str:
    normalized = status.lower()
    if "demo" in normalized or "fixture" in normalized or "format" in normalized:
        return "demo-only-not-evidence"
    if passed_statistical_threshold:
        return "passed-preregistered-threshold"
    return "not-supported-by-current-data"

def build_public_figure_manifest(
    source_xml: str | Path,
    output_path: str | Path,
    *,
    ratings: set[str] | frozenset[str] = DEFAULT_RATINGS,
    split_seed: str = DEFAULT_SPLIT_SEED,
) -> PublicFigureManifestSummary:
    source = Path(source_xml)
    output = Path(output_path)
    root = ET.parse(source).getroot()
    records: list[dict[str, Any]] = []
    rating_counts: dict[str, int] = {}
    split_counts = {"train": 0, "validation": 0, "holdout": 0}

for entry in root.findall("adb_entry"):
        public_data = entry.find("public_data")
        if public_data is None:
            continue
        data_type = _attr(public_data.find("datatype"), "sdatatype")
        rating = (public_data.findtext("roddenrating") or "").strip()
        if data_type != "Public Figure" or rating not in ratings:
            continue
        bdata = public_data.find("bdata")
        sbtime = bdata.find("sbtime") if bdata is not None else None
        if bdata is None or sbtime is None or not sbtime.text or not _attr(sbtime, "jd_ut"):
            continue

"blind_safe": {
            "strip_name": True,
            "strip_birth_place": True,
            "strip_occupation_categories": True,
            "strip_identifying_biography": True,
        },
        "record_hash": sha256(f"{adb_id}:{rating}:{birth_year}:{split_seed}".encode("utf-8")).hexdigest(),
    }

def deterministic_split(sample_id: str, seed: str = DEFAULT_SPLIT_SEED) -> str:
    value = int(sha256(f"{seed}:{sample_id}".encode("utf-8")).hexdigest()[:8], 16) / 0xFFFFFFFF
    if value < 0.58:
        return "train"
    if value < 0.78:
        return "validation"
    return "holdout"

def _categories(entry: ET.Element) -> list[str]:
    categories = entry.find("research_data/categories")
    if categories is None:
        return []
    return sorted(
        category.text.strip()
        for category in categories.findall("category")
        if category.text and category.text.strip()
    )

def _attr(element: ET.Element | None, key: str) -> str:
    if element is None:
        return ""
    return element.attrib.get(key, "")

def _choose_decoys(
    target: dict[str, Any],
    records: list[dict[str, Any]],
    rng: random.Random,
    count: int,
) -> list[dict[str, Any]]:
    target_year = target["birth"]["year"]
    same_gender = [
        record
        for record in records
        if record["sample_id"] != target["sample_id"] and record["gender"] == target["gender"]
    ]
    candidates = sorted(
        same_gender or [record for record in records if record["sample_id"] != target["sample_id"]],
        key=lambda item: (abs(item["birth"]["year"] - target_year), item["sample_id"]),
    )
    if len(candidates) < count:
        candidates = sorted(
            [record for record in records if record["sample_id"] != target["sample_id"]],
            key=lambda item: (abs(item["birth"]["year"] - target_year), item["sample_id"]),
        )
    nearest_pool = candidates[: max(50, count * 8)]
    if len(nearest_pool) < count:
        raise ValueError(f"not enough decoys for {target['sample_id']}: needed={count} available={len(nearest_pool)}")
    return rng.sample(nearest_pool, count)

def _blind_prompt_profile(record: dict[str, Any]) -> dict[str, Any]:
    labels = record.get("labels", {})
    return {
        "gender": record.get("gender"),
        "birth_year_bucket": _year_bucket(record["birth"]["year"]),
        "target_label_counts": {
            "vocation": len(labels.get("vocation", [])),
            "traits": len(labels.get("traits", [])),
            "life_events": len(labels.get("life_events", [])),
        },
    }

def _year_bucket(year: int) -> str:
    if year <= 0:
        return "unknown"
    return f"{year // 10 * 10}s"

def _write_jsonl(path: str | Path, rows: list[dict[str, Any]]) -> None:
    output = Path(path)
    output.parent.mkdir(parents=True, exist_ok=True)
    with output.open("w", encoding="utf-8") as handle:
        for row in rows:
            handle.write(json.dumps(row, ensure_ascii=False, sort_keys=True) + "\n")

