def _difference_bullet(label: str, kind: str, values, formatter) -> str:
    if not values:
        return f"{label} 的独有{kind}：当前不明显，说明在这层结构上不会总是由一方单边主导。"
    return f"{label} 的独有{kind}：{formatter(values)}。这些议题更容易由 {label} 先带出节奏或先感到在意。"

