def normalize_depth(depth: str | None) -> str:
    if depth in DEPTH_MODES:
        return depth
    return "standard"

def select_sections_by_depth(items: tuple[T, ...], depth: str) -> tuple[T, ...]:
    if depth == "brief":
        return items[:2]
    return items

def followups_by_depth(items: tuple[str, ...], depth: str) -> tuple[str, ...]:
    if depth == "brief":
        return items[:2]
    return items

def highlight_limit(depth: str) -> int:
    if depth == "brief":
        return 3
    if depth == "deep":
        return 7
    return 5

def _code_delta(natal: tuple[str, ...], transit: tuple[str, ...]) -> TimingCodeDelta:
    natal_set = set(natal)
    transit_set = set(transit)
    return TimingCodeDelta(
        shared=tuple(item for item in natal if item in transit_set),
        natal_only=tuple(item for item in natal if item not in transit_set),
        transit_only=tuple(item for item in transit if item not in natal_set),
    )

def _int_delta(natal: tuple[int, ...], transit: tuple[int, ...]) -> TimingIntDelta:
    natal_set = set(natal)
    transit_set = set(transit)
    return TimingIntDelta(
        shared=tuple(item for item in natal if item in transit_set),
        natal_only=tuple(item for item in natal if item not in transit_set),
        transit_only=tuple(item for item in transit if item not in natal_set),
    )

